from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def segment(values):
        cells = [(i, v) for i, v in enumerate(values) if v != bg]
        if not cells or len({v for _, v in cells}) != 1:
            return None
        indices = [i for i, _ in cells]
        if indices != list(range(indices[0], indices[-1] + 1)):
            return None
        return indices[0], indices[-1] + 1, cells[0][1]

    top, bottom = segment(grid[0]), segment(grid[-1])
    if top and bottom and top[1] - top[0] == bottom[1] - bottom[0] and top[2] == bottom[2]:
        # A marker in the lane aligned with the top bar extends upward to the
        # top boundary. Markers in the bottom bar's lane extend to the right
        # edge; markers inside the frame are turned into color 4.
        for r in range(1, h - 1):
            for c in range(top[0], top[1]):
                color = grid[r][c]
                if color == bg:
                    continue
                mapped_c = bottom[0] + c - top[0]
                for rr in range(0, r):
                    if grid[rr][c] == bg:
                        out[rr][c] = color
                for rr in range(h):
                    if grid[rr][mapped_c] == bg:
                        out[rr][mapped_c] = color
                out[r][c] = 4
        return out

    left, right = segment([grid[r][0] for r in range(h)]), segment([grid[r][-1] for r in range(h)])
    if left and right and left[1] - left[0] == right[1] - right[0] and left[2] == right[2]:
        # The rotated counterpart: markers in the right lane project leftward
        # and create a full-width ray in the corresponding left lane.
        for r in range(right[0], right[1]):
            for c in range(1, w - 1):
                color = grid[r][c]
                if color == bg:
                    continue
                mapped_r = left[0] + r - right[0]
                for cc in range(c + 1, w):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
                for cc in range(w):
                    if grid[mapped_r][cc] == bg:
                        out[mapped_r][cc] = color
                out[r][c] = 4
        return out
    return out


